<?php /* Template Name: FINNORA — Design Library */
get_header();
$slug=sanitize_title(fin_input('design'));
if($slug){$design=fin_design_record(get_page_by_path($slug,OBJECT,'fin_design'));if($design){include get_template_directory().'/template-parts/design-builder.php';}else{echo '<section class="container fin-design-page"><h1>Design not found</h1><p>This design is no longer available.</p><a class="button" href="'.esc_url(fin_design_page_url()).'">Explore designs</a></section>';}}
else {
    $seasonal=get_page_template_slug()==='page-christmas.php';
    $mood=sanitize_key(fin_input('mood'));$topic=sanitize_key(fin_input('topic'));$style=sanitize_key(fin_input('style'));$personal=sanitize_key(fin_input('personal'));$query=sanitize_text_field(fin_input('q'));
    $all=fin_design_records($seasonal);$filtered=array_values(array_filter($all,function($d)use($topic,$style,$personal,$query,$mood){return (!$mood||in_array($mood,fin_design_term_slugs($d['id'],'fin_holiday_mood'),true))&&(!$topic||in_array($topic,fin_design_term_slugs($d['id'],'fin_topic'),true))&&(!$style||in_array($style,fin_design_term_slugs($d['id'],'fin_style'),true))&&(!$personal||in_array($personal,fin_design_term_slugs($d['id'],'fin_personalization'),true))&&(!$query||stripos($d['name'].' '.$d['description'].' '.implode(' ',array_merge(fin_design_term_slugs($d['id'],'fin_topic'),fin_design_term_slugs($d['id'],'fin_style'))),$query)!==false);}));
    $title=$seasonal?'Christmas Collection':($topic&&isset(fin_design_topics()[$topic])?fin_design_topics()[$topic][0]:'Explore designs');
    $intro=$seasonal?'A festive idea, with your own personality.':($topic&&isset(fin_design_topics()[$topic])?fin_design_topics()[$topic][1]:'Choose an idea. Make it yours.');
    $limit=max(12,min(120,absint(fin_input('show'))?:12));
    ?><section class="container fin-design-page"><header class="fin-design-page-head"><div><h1><?php echo esc_html($title); ?></h1><p><?php echo esc_html($intro); ?></p></div><a class="button button-outline" href="<?php echo esc_url(fin_design_page_url('upload')); ?>">Upload your photo ↗</a></header>
    <nav class="fin-topic-chips" aria-label="Design topics"><a href="<?php echo esc_url(get_permalink()); ?>" <?php if(!$topic)echo 'aria-current="page"'; ?>>All topics</a><?php foreach(fin_design_topics() as $key=>[$name]) : ?><a href="<?php echo esc_url(add_query_arg('topic',$key,get_permalink())); ?>" <?php if($topic===$key)echo 'aria-current="page"'; ?>><?php echo esc_html($name); ?></a><?php endforeach; ?></nav>
    <details class="fin-design-filters" open><summary>Filter designs</summary><form method="get" action="<?php echo esc_url(get_permalink()); ?>"><label class="fin-mobile-topic-filter">Topic<select name="topic"><option value="">All topics</option><?php foreach(fin_design_topics() as $topic_slug=>[$topic_name]):?><option value="<?php echo esc_attr($topic_slug); ?>" <?php selected($topic,$topic_slug); ?>><?php echo esc_html($topic_name); ?></option><?php endforeach; ?></select></label><label>Search designs<input type="search" name="q" value="<?php echo esc_attr($query); ?>" placeholder="Try pets, botanical or a design name"></label><?php foreach(['style'=>['Style','fin_style'],'personal'=>['Personalization','fin_personalization']] as $key=>[$label,$tax]):$terms=get_terms(['taxonomy'=>$tax,'hide_empty'=>true]);?><label><?php echo esc_html($label); ?><select name="<?php echo esc_attr($key); ?>"><option value=""><?php echo $key==='style'?'All styles':'All options'; ?></option><?php if(!is_wp_error($terms))foreach($terms as $term):?><option value="<?php echo esc_attr($term->slug); ?>" <?php selected($key==='style'?$style:$personal,$term->slug); ?>><?php echo esc_html($term->name); ?></option><?php endforeach; ?></select></label><?php endforeach; ?><label>Christmas mood<select name="mood"><option value="">All moods</option><?php foreach(fin_holiday_2026_moods() as $key=>$label):?><option value="<?php echo esc_attr($key); ?>" <?php selected($mood,$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><button class="button">Show designs</button></form></details>
    <div class="fin-design-results"><p><?php echo esc_html(count($filtered)); ?> designs · Featured</p><?php if($topic||$style||$personal||$query||$mood):?><div class="fin-applied-filters" aria-label="Active filters"><?php foreach(['Topic'=>$topic,'Style'=>$style,'Personalization'=>$personal,'Search'=>$query,'Mood'=>$mood] as $label=>$value)if($value)echo '<span>'.esc_html($label.': '.ucwords(str_replace('-',' ',$value))).'</span>';?><a href="<?php echo esc_url(get_permalink()); ?>">Clear all</a></div><?php endif; ?></div>
    <?php if($filtered):?><div class="fin-design-grid"><?php foreach(array_slice($filtered,0,$limit) as $design)fin_design_card($design); ?></div><?php if(count($filtered)>$limit):?><a class="button button-outline fin-design-more" href="<?php echo esc_url(add_query_arg('show',$limit+12)); ?>">Show more designs</a><?php endif; ?><?php else:?><div class="fin-design-empty"><h2>No designs match those choices.</h2><p>Try removing a style or personalization filter, or search for a different word.</p><a class="button button-outline" href="<?php echo esc_url(get_permalink()); ?>">Clear all filters</a></div><?php endif; ?><p class="fin-design-disclosure">Original demonstration artworks. Previews are illustrative; this store has no connected print-production service.</p></section><?php
}
get_footer();
